}

.itinerary-item-details {
    flex: 1;
}

.itinerary-item-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 15px;
    margin-bottom: 8px;
}

.itinerary-item-name {
    font-size: 1.2em;
    font-weight: 600;
