}

.itinerary-item-schedule {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 8px 12px;
    background: #eef6ff;
    border-radius: 6px;
    font-size: 0.88em;
    color: #1a5276;
    margin-bottom: 10px;
    border-left: 3px solid #3498db;
}

.itinerary-item-schedule .schedule-icon {
    font-size: 1em;
    flex-shrink: 0;
}

.itinerary-item-schedule .schedule-text {
    font-weight: 500;
}

.itinerary-item-description {
    font-size: 0.9em;
    color: #555;
    line-height: 1.5;
    margin-bottom: 10px;
}

.itinerary-item-reactions {
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid #eee;
}

.itinerary-item-reactions .reaction-bar-buttons {
    display: flex;
    gap: 5px;
    flex-wrap: wrap;
    margin-bottom: 8px;
}

.itinerary-item-reactions .reaction-btn {
    background: #f0f0f0;
