}

.itinerary-item-reactions .reaction-summary-display {
    font-size: 0.8em;
    color: #6c757d;
}

/* Expand/More Details Button for itinerary items */
.itinerary-item-expand-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-top: 12px;
    padding: 8px 14px;
    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
    border: 1px solid #dee2e6;
    border-radius: 8px;
    font-size: 0.85em;
    font-weight: 500;
    color: #495057;
    cursor: pointer;
    transition: all 0.2s ease;
