}

.presentation-suggestion-btn:active {
    transform: translateY(0);
}

.presentation-suggestion-btn:focus-visible {
    outline: 2px solid rgba(99, 102, 241, 0.8);
    outline-offset: 2px;
}

/* Mobile responsive for itinerary */
@media (max-width: 768px) {
    .presentation-header .header-content {
        padding: 0.75rem 1rem;
        gap: 10px;
    }

    .presentation-shop-title {
