        margin-bottom: 15px;
    }

    .itinerary-event-title {
        font-size: 1.5em;
    }

    .itinerary-item {
        flex-direction: column;
        gap: 15px;
        padding: 15px;
    }

    .itinerary-item-number {
        width: 30px;
        height: 30px;
        font-size: 0.9em;
    }

    .itinerary-main-image {
