    }

    .collaborators-modal-content {
        width: 95%;
        max-height: 80vh;
    }

    .itinerary-chat-messages {
        max-height: 300px;
    }
}

/* Accordion Styles for Presentation View */
.itinerary-accordion {
    overflow: hidden;
}

.itinerary-accordion-header {
    cursor: pointer;
    padding: 15px 0;
    user-select: none;
    transition: padding 0.3s ease;
}

.itinerary-accordion-header:hover {
    background: rgba(0, 123, 255, 0.03);
}

.itinerary-accordion-title-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 15px;
}

.itinerary-accordion-title {
    font-size: 1.3em;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.95);
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.3);
    margin: 0;
    padding-bottom: 0;
    border-bottom: none;
}

.itinerary-accordion-icon {
    display: inline-block;
    width: 24px;
    height: 24px;
    position: relative;
    flex-shrink: 0;
    transition: transform 0.3s ease;
}

.itinerary-accordion-icon::before,
.itinerary-accordion-icon::after {
    content: '';
    position: absolute;
    background-color: rgba(255, 255, 255, 0.9);
    transition: transform 0.3s ease, opacity 0.3s ease;
}

.itinerary-accordion-icon::before {
    width: 2px;
    height: 14px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

.itinerary-accordion-icon::after {
    width: 14px;
    height: 2px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

/* Expanded state - hide the vertical line to show minus */
.itinerary-accordion.expanded .itinerary-accordion-icon::before {
    transform: translate(-50%, -50%) rotate(90deg);
    opacity: 0;
}

.itinerary-accordion-summary {
    font-size: 0.9em;
    color: rgba(255, 255, 255, 0.7);
    text-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
    margin: 10px 0 0 0;
    line-height: 1.4;
    max-height: 60px;
    overflow: hidden;
    transition: opacity 0.3s ease, max-height 0.3s ease;
}

/* Hide summary when expanded */
.itinerary-accordion.expanded .itinerary-accordion-summary {
    opacity: 0;
    max-height: 0;
    margin-top: 0;
}

/* Accordion section title (e.g., plan name in header) */
.accordion-section-title {
    font-size: 1.2em;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.95);
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.3);
    margin: 0;
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    opacity: 1;
    transition: opacity 0.3s ease;
}

/* Accordion section title stays visible in both collapsed and expanded states */
.itinerary-accordion:not(.expanded) .accordion-section-title {
    opacity: 1;
}

.itinerary-accordion-content {
    max-height: 0;
    overflow: hidden;
    transition: max-height 0.4s ease, padding 0.3s ease;
    padding-top: 0;
}

/* Expanded state */
.itinerary-accordion.expanded .itinerary-accordion-content {
    max-height: 3000px;
    padding-top: 15px;
    overflow: visible;
}

/* Remove old title styling when inside accordion */
.itinerary-accordion .itinerary-section-title {
    display: none;
}

/* Adjust header section styling for accordion */
.itinerary-accordion.itinerary-header {
    text-align: left;
}

.itinerary-accordion.itinerary-header.expanded {
    text-align: center;
}

