    margin: 0;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Item Emoji Indicator - Real-time reaction summary next to item name */
.item-emoji-indicator {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 2px 8px;
    border-radius: 12px;
    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
    font-size: 0.9em;
    flex-shrink: 0;
    transition: all 0.3s ease;
    animation: emoji-pop 0.3s ease-out;
}

.item-emoji-indicator.has-reactions {
    background: linear-gradient(135deg, #fff3cd 0%, #ffeaa7 100%);
    box-shadow: 0 2px 8px rgba(255, 193, 7, 0.2);
}

.item-emoji-indicator .emoji-indicator-emoji {
    font-size: 1.1em;
    line-height: 1;
}

.item-emoji-indicator .emoji-indicator-count {
    font-size: 0.75em;
    font-weight: 600;
    color: #6c757d;
    background: rgba(0, 0, 0, 0.08);
    padding: 1px 5px;
    border-radius: 8px;
    min-width: 16px;
    text-align: center;
}

@keyframes emoji-pop {
    0% {
        transform: scale(0.8);
        opacity: 0;
    }
    50% {
        transform: scale(1.1);
    }
    100% {
        transform: scale(1);
        opacity: 1;
    }
}

/* Ranking summary emoji styles */
.ranking-summary-emoji {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    background: linear-gradient(135deg, #f8f9fa 0%, #e9ecef 100%);
