    color: #6c757d;
}

.item-accordion-title-row .itinerary-item-type {
    flex-shrink: 0;
}

/* Item Accordion Icon (plus/minus) */
.item-accordion-icon {
    display: inline-block;
    width: 20px;
    height: 20px;
    position: relative;
    flex-shrink: 0;
    transition: transform 0.3s ease;
}

.item-accordion-icon::before,
.item-accordion-icon::after {
    content: '';
    position: absolute;
    background-color: #007bff;
    transition: transform 0.3s ease, opacity 0.3s ease;
}

.item-accordion-icon::before {
    width: 2px;
    height: 12px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

.item-accordion-icon::after {
    width: 12px;
    height: 2px;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
}

/* Expanded state - hide vertical line to show minus */
.item-accordion.expanded .item-accordion-icon::before {
    transform: translate(-50%, -50%) rotate(90deg);
    opacity: 0;
}

/* Item Accordion Summary - Shown when collapsed */
.item-accordion-summary {
    font-size: 0.85em;
    color: #6c757d;
    margin: 10px 0 0 0;
    padding-left: 40px;
    line-height: 1.4;
    max-height: 50px;
    overflow: hidden;
    transition: opacity 0.3s ease, max-height 0.3s ease, margin 0.3s ease;
}

/* Hide summary when expanded */
