/* ============================================
   MODAL REACTIONS BAR (above modal)
   ============================================ */

/* Reactions bar floats above the modal content box */
.modal-reactions-section {
    display: none;
    flex-direction: row;
    align-items: center;
    gap: 6px;
    background: rgba(255, 255, 255, 0.95);
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border-radius: 24px;
    padding: 6px 12px;
    margin-bottom: 8px;
    box-shadow: 0 2px 16px rgba(0, 0, 0, 0.15), 0 0 0 1px rgba(255, 255, 255, 0.2);
    max-width: 90%;
    width: auto;
    flex-wrap: wrap;
    justify-content: center;
    position: relative;
    z-index: 1001;
}

.modal-reactions-score-badge {
    font-size: 0.72em;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 10px;
    display: none;
    white-space: nowrap;
}

.modal-reactions-score-badge.score-positive {
    background: linear-gradient(135deg, #d4edda, #c3e6cb);
    color: #155724;
}

.modal-reactions-score-badge.score-negative {
    background: linear-gradient(135deg, #f8d7da, #f5c6cb);
    color: #721c24;
}

.modal-reactions-score-badge.score-neutral {
    background: linear-gradient(135deg, #e2e3e5, #d6d8db);
    color: #383d41;
}

/* Quick reaction bar */
.modal-reactions-quick-bar {
    display: flex;
    flex-wrap: nowrap;
    gap: 3px;
}

.modal-reaction-btn {
    background: transparent;
    border: 1.5px solid transparent;
    border-radius: 8px;
    padding: 3px 6px;
    cursor: pointer;
    font-size: 1.2em;
    line-height: 1;
    transition: all 0.15s ease;
    position: relative;
}

.modal-reaction-btn:hover {
    background: rgba(0, 0, 0, 0.06);
    transform: scale(1.2);
}

.modal-reaction-btn.selected {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border-color: #667eea;
    box-shadow: 0 2px 8px rgba(102, 126, 234, 0.3);
    border-radius: 8px;
}

/* Expand button - compact for top bar */
.modal-reactions-expand-btn {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    background: none;
    border: 1px dashed #ced4da;
    border-radius: 12px;
    padding: 3px 8px;
    color: #6c757d;
    font-size: 0.72em;
    cursor: pointer;
    transition: all 0.15s ease;
    white-space: nowrap;
}

.modal-reactions-expand-btn:hover {
    border-color: #667eea;
    color: #667eea;
    background: rgba(102, 126, 234, 0.06);
}

.expand-btn-icon {
    font-weight: bold;
    font-size: 1.1em;
}

/* Tiered emoji picker - positioned as dropdown from the bar */
.modal-reactions-picker {
    position: absolute;
    top: 100%;
    left: 50%;
    transform: translateX(-50%);
    max-height: 320px;
    max-width: 400px;
    width: 90vw;
    overflow-y: auto;
    border: 1px solid #e9ecef;
    border-radius: 12px;
    padding: 10px;
    margin-top: 6px;
    background: #fff;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
    scroll-behavior: smooth;
    z-index: 1002;
}

.modal-reactions-picker::-webkit-scrollbar {
    width: 6px;
}

.modal-reactions-picker::-webkit-scrollbar-track {
    background: transparent;
}

.modal-reactions-picker::-webkit-scrollbar-thumb {
    background: #ced4da;
    border-radius: 3px;
}

.modal-emoji-tiers-scroll {
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.modal-emoji-tier {
    padding-bottom: 10px;
    border-bottom: 1px solid #e9ecef;
}

