    font-size: 0.78em;
    font-weight: 700;
    color: #495057;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.modal-emoji-tier-header .tier-description {
    font-size: 0.7em;
    color: #868e96;
    font-style: italic;
}

.modal-emoji-tier-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
}

.modal-tier-emoji {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 4px 6px 2px;
    min-width: 38px;
    background: #fff;
    border: 1px solid #e9ecef;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.15s ease;
}

.modal-tier-emoji:hover {
    background: #f0f0f0;
