/* --- ADD TO END of style.css --- */

/* New context header for cutout picker */
#cutout-picker-context {
    display: flex;
    align-items: center;
    gap: 15px;
    padding-bottom: 10px;
    border-bottom: 1px solid #eee;
}
#cutout-context-thumb {
