    animation: merge-dialog-slide-up 0.3s ease;
    max-height: 90vh;
    overflow-y: auto;
}

@keyframes merge-dialog-slide-up {
    from {
        transform: translateY(30px);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

.merge-dialog-close {
    position: absolute;
    top: 12px;
    right: 12px;
    background: rgba(0, 0, 0, 0.1);
    border: none;
    width: 32px;
    height: 32px;
    border-radius: 50%;
