/* === Group Detail Modal Styles === */
.group-modal-image-grid {
    width: 100%;
    height: 100%;
    display: grid;
    gap: 4px;
    border-radius: 8px;
    overflow: hidden;
}

.group-modal-image-grid.single {
    grid-template-columns: 1fr;
}

.group-modal-image-grid.two {
    grid-template-columns: 1fr 1fr;
}

.group-modal-image-grid.three {
    grid-template-columns: 1fr 1fr;
    grid-template-rows: 1fr 1fr;
}

.group-modal-image-grid.three .group-modal-image-cell:first-child {
    grid-column: 1 / -1;
}

.group-modal-image-grid.multi {
    grid-template-columns: 1fr 1fr 1fr;
    grid-template-rows: auto;
}

.group-modal-image-cell {
    background-size: cover;
    background-position: center;
    min-height: 120px;
}

.group-modal-image-placeholder {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    width: 100%;
    height: 100%;
    background: linear-gradient(135deg, #f5f9ff 0%, #eef5ff 100%);
    color: #90a4ae;
    font-size: 0.9em;
}

.group-modal-image-placeholder-icon {
    font-size: 3em;
    opacity: 0.5;
}

/* Group options container in modal */
.group-options-container {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 4px 0;
}

.group-options-label {
    font-size: 0.85em;
    font-weight: 600;
    color: #1565c0;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    padding-bottom: 4px;
    border-bottom: 2px solid #e3f2fd;
}

/* Individual option card in group modal */
.group-option-card {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 10px 12px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.2s ease;
}

.group-option-card:hover {
    border-color: #2196F3;
    background: linear-gradient(135deg, #f5f9ff 0%, #eef5ff 100%);
    box-shadow: 0 2px 8px rgba(33, 150, 243, 0.15);
    transform: translateX(2px);
}

.group-option-card:focus {
    outline: 2px solid #2196F3;
    outline-offset: 2px;
}

.group-option-card-image {
    width: 56px;
    height: 56px;
    border-radius: 8px;
    background-size: cover;
    background-position: center;
    background-color: #f5f5f5;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}

.group-option-card-no-img {
    font-size: 1.4em;
    opacity: 0.3;
}

.group-option-card-info {
    flex: 1;
    min-width: 0;
}

.group-option-card-name {
    font-weight: 600;
    font-size: 0.92em;
    color: #333;
    margin-bottom: 2px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.group-option-card-desc {
    font-size: 0.78em;
    color: #777;
    line-height: 1.3;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
}

.group-option-card-price {
    font-size: 0.82em;
    font-weight: 600;
    color: #2e7d32;
    margin-top: 2px;
}

.group-option-card-arrow {
    font-size: 1.1em;
    color: #bbb;
    flex-shrink: 0;
    transition: color 0.2s ease, transform 0.2s ease;
}

.group-option-card:hover .group-option-card-arrow {
    color: #2196F3;
    transform: translateX(3px);
}

/* Remove button inside group option card in modal */
.group-option-card-remove {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border: 1px solid rgba(198, 40, 40, 0.15);
    background: rgba(198, 40, 40, 0.06);
    color: #c62828;
    border-radius: 50%;
    cursor: pointer;
    font-size: 0.8em;
    flex-shrink: 0;
    transition: background 0.15s ease, border-color 0.15s ease;
    opacity: 0;
}

.group-option-card:hover .group-option-card-remove {
    opacity: 1;
}

.group-option-card-remove:hover {
    background: rgba(198, 40, 40, 0.18);
    border-color: rgba(198, 40, 40, 0.3);
}

/* Always show remove button on touch devices */
@media (hover: none) {
    .group-option-card-remove {
        opacity: 1;
    }
}

/* Dissolve button inside group modal */
.group-dissolve-modal-btn {
    padding: 8px 16px;
    background: rgba(198, 40, 40, 0.06);
    border: 1px solid rgba(198, 40, 40, 0.2);
    border-radius: 8px;
    color: #c62828;
    font-size: 0.82em;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    margin-top: 4px;
    align-self: center;
    width: 100%;
    text-align: center;
}

.group-dissolve-modal-btn:hover {
    background: rgba(198, 40, 40, 0.12);
    border-color: rgba(198, 40, 40, 0.4);
}

/* Group breadcrumb styling */
.group-breadcrumb-label {
    color: #1565c0;
    font-weight: 500;
    font-size: 0.85em;
}

.group-back-link {
    color: #1565c0;
    cursor: pointer;
    font-weight: 500;
    font-size: 0.85em;
    text-decoration: none;
    transition: color 0.2s ease;
}

.group-back-link:hover {
    color: #0d47a1;
    text-decoration: underline;
}

/* Combined item visual enhancement */
.itinerary-item-section.is-combined {
    border-left: 3px solid #9C27B0;
}

.itinerary-item-section.is-combined .itinerary-item {
    background: linear-gradient(135deg, #faf5fc 0%, #f3e5f5 100%);
}

/* Source items that have been combined into another (hidden/collapsed) */
.itinerary-item-section.combined-source {
    display: none;
}

/* Expandable combined sources list */
.combined-sources-section {
    padding: 8px 16px;
    background: rgba(156, 39, 176, 0.05);
    border-top: 1px dashed rgba(156, 39, 176, 0.3);
}

.combined-sources-toggle {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.85em;
    color: #7b1fa2;
    cursor: pointer;
    background: none;
    border: none;
    padding: 4px 8px;
    border-radius: 6px;
    transition: background 0.2s ease;
}

.combined-sources-toggle:hover {
    background: rgba(156, 39, 176, 0.1);
}

.combined-sources-list {
    margin-top: 8px;
    padding-left: 12px;
    border-left: 2px solid rgba(156, 39, 176, 0.3);
}

.combined-hybrid-description {
    font-size: 0.85em;
    color: #6c757d;
    font-style: italic;
    padding: 8px 0;
    margin-bottom: 8px;
    border-bottom: 1px solid rgba(156, 39, 176, 0.15);
    line-height: 1.4;
}

/* Combined sources header with split action */
.combined-sources-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

.uncombine-all-btn {
    font-size: 0.78em;
    color: #dc3545;
    background: rgba(220, 53, 69, 0.08);
    border: 1px solid rgba(220, 53, 69, 0.2);
    border-radius: 6px;
    padding: 4px 10px;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    font-weight: 500;
}

.uncombine-all-btn:hover {
    background: rgba(220, 53, 69, 0.15);
    border-color: rgba(220, 53, 69, 0.4);
}

/* Uncombine individual source button */
.uncombine-source-btn {
    flex-shrink: 0;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    border: 1px solid rgba(156, 39, 176, 0.25);
    background: rgba(156, 39, 176, 0.06);
    color: #7b1fa2;
    font-size: 0.75em;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    padding: 0;
    line-height: 1;
}

.uncombine-source-btn:hover {
    background: rgba(220, 53, 69, 0.15);
    border-color: rgba(220, 53, 69, 0.4);
    color: #dc3545;
}

.combined-source-item {
    font-size: 0.85em;
    color: #666;
    padding: 4px 0;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
}

/* Leave group button (inside group indicator) */
.leave-group-btn {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 1px solid rgba(21, 101, 192, 0.25);
    background: rgba(21, 101, 192, 0.06);
    color: #1565c0;
    font-size: 0.65em;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    padding: 0;
    line-height: 1;
    margin-left: 2px;
}

.leave-group-btn:hover {
    background: rgba(220, 53, 69, 0.15);
    border-color: rgba(220, 53, 69, 0.4);
    color: #dc3545;
}

/* Hybrid indicator styling */
.item-combined-indicator.has-hybrid {
    background: linear-gradient(135deg, #f3e5f5 0%, #e1bee7 100%);
    border: 1px solid rgba(156, 39, 176, 0.3);
}

/* Group indicator with name */
.item-group-indicator .group-name {
    font-weight: 600;
    max-width: 100px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.item-group-indicator .group-count {
    font-size: 0.9em;
    opacity: 0.8;
}

/* =============================================================================
   BOARD VIEW - Compact Card Grid (v3.6 Plan Board)
   ============================================================================= */

/* Grid layout for board view */
.itinerary-items-list.board-view {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 16px;
    max-width: 100%;
}

@media (max-width: 480px) {
    .itinerary-items-list.board-view {
        grid-template-columns: 1fr;
        gap: 12px;
    }
}

@media (min-width: 481px) and (max-width: 768px) {
    .itinerary-items-list.board-view {
        grid-template-columns: repeat(2, 1fr);
    }
}

/* Compact card tile */
.compact-card {
    position: relative;
    border-radius: 12px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.12);
    backdrop-filter: blur(8px);
    -webkit-backdrop-filter: blur(8px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    cursor: pointer;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.compact-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
}

.compact-card:active {
    transform: translateY(0);
}

/* Photo section */
.compact-card-photo {
    width: 100%;
    aspect-ratio: 16 / 10;
    background-size: cover;
    background-position: center;
    background-color: rgba(255, 255, 255, 0.05);
    position: relative;
}

.compact-card-no-photo .compact-card-photo {
    background: linear-gradient(135deg, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0.03) 100%);
    display: flex;
    align-items: center;
    justify-content: center;
}

.compact-card-no-photo .compact-card-photo::after {
    content: '📷';
    font-size: 2em;
    opacity: 0.3;
}

/* Floating status overlay (top-left) */
.compact-card-status {
    position: absolute;
    top: 8px;
    left: 8px;
    padding: 3px 8px;
    border-radius: 12px;
    background: rgba(0, 0, 0, 0.6);
    color: white;
    font-size: 0.72em;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 3px;
    z-index: 2;
    backdrop-filter: blur(4px);
}

.compact-card-status.task-status-gtg {
    background: rgba(40, 167, 69, 0.8);
}

.compact-card-status.task-status-check {
    background: rgba(255, 193, 7, 0.8);
    color: #333;
}

.compact-card-status.task-status-attention,
.compact-card-status.task-status-needs-attention {
    background: rgba(220, 53, 69, 0.8);
}

.compact-card-status.task-status-no-action {
    background: rgba(108, 117, 125, 0.7);
}

/* Floating emoji overlay (top-right) */
.compact-card-emoji {
    position: absolute;
    top: 8px;
    right: 8px;
    padding: 3px 8px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.9);
    cursor: help;
    font-size: 1em;
    z-index: 2;
    display: inline-flex;
    align-items: center;
    gap: 2px;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.15);
}

.compact-card-emoji-count {
    font-size: 0.75em;
    font-weight: 600;
    color: #555;
}

/* Group badge on photo */
.compact-card-group-badge {
    position: absolute;
    bottom: 8px;
    left: 8px;
    padding: 3px 10px;
    border-radius: 12px;
    background: rgba(0, 0, 0, 0.6);
    color: white;
    font-size: 0.72em;
    font-weight: 500;
    backdrop-filter: blur(4px);
}

/* Card body */
.compact-card-body {
    padding: 12px;
}

.compact-card-title-row {
    display: flex;
    align-items: center;
    gap: 4px;
}

.compact-card-goal-badge {
    font-size: 0.85em;
    flex-shrink: 0;
}

.compact-card-name {
    font-weight: 600;
    font-size: 0.95em;
    color: rgba(255, 255, 255, 0.95);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    margin: 0;
    flex: 1;
    min-width: 0;
}

/* Split button on compact cards (group and hybrid) */
.compact-card-split-btn {
    flex-shrink: 0;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.15);
    color: rgba(255, 255, 255, 0.7);
    font-size: 0.8em;
    padding: 2px 6px;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.2s ease;
    line-height: 1;
    display: flex;
    align-items: center;
    justify-content: center;
}

.compact-card-split-btn:hover {
    background: rgba(244, 67, 54, 0.25);
    border-color: rgba(244, 67, 54, 0.5);
    color: #ff8a80;
    transform: scale(1.1);
}

.compact-card-split-btn:active {
    transform: scale(0.95);
}

/* Split button in provenance line for hybrids */
.compact-card-split-hybrid {
    margin-left: auto;
    font-size: 0.85em;
    padding: 1px 5px;
}

/* Provenance line */
.compact-card-provenance {
    font-size: 0.78em;
    color: rgba(255, 255, 255, 0.5);
    margin-top: 4px;
    display: flex;
    align-items: center;
    gap: 4px;
    flex-wrap: wrap;
    overflow: hidden;
}

.provenance-label {
    color: rgba(255, 255, 255, 0.4);
    font-size: 0.9em;
    font-weight: 500;
    flex-shrink: 0;
}

.provenance-hybrid-icon {
    flex-shrink: 0;
    font-size: 1em;
}

.provenance-source-badge {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 1px 6px;
    border-radius: 8px;
    font-size: 0.88em;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 110px;
    background: rgba(255, 255, 255, 0.08);
    color: rgba(255, 255, 255, 0.7);
    border: 1px solid rgba(255, 255, 255, 0.06);
}

.provenance-source-ai {
    background: rgba(99, 102, 241, 0.15);
    border-color: rgba(99, 102, 241, 0.25);
    color: rgba(165, 168, 255, 0.9);
}

.provenance-source-solution {
    background: rgba(245, 158, 11, 0.12);
    border-color: rgba(245, 158, 11, 0.2);
    color: rgba(255, 200, 100, 0.9);
}

.provenance-source-manual {
    background: rgba(16, 185, 129, 0.12);
    border-color: rgba(16, 185, 129, 0.2);
    color: rgba(110, 231, 183, 0.9);
}

.provenance-source-catalog {
    background: rgba(255, 255, 255, 0.06);
    border-color: rgba(255, 255, 255, 0.1);
}

.provenance-source-more {
    background: rgba(255, 255, 255, 0.05);
    color: rgba(255, 255, 255, 0.4);
    font-style: italic;
    font-size: 0.85em;
}

/* Variation pills */
.compact-card-pills {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
    margin-top: 8px;
}

.compact-card-pill {
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 0.7em;
    background: rgba(255, 255, 255, 0.12);
    color: rgba(255, 255, 255, 0.8);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 120px;
}

.compact-card-pill-more {
    background: rgba(255, 255, 255, 0.08);
    color: rgba(255, 255, 255, 0.5);
    font-style: italic;
}

/* Bottom meta bar */
.compact-card-meta {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 8px;
    padding-top: 8px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
    font-size: 0.8em;
    min-height: 24px;
}

.compact-card-reactions {
    display: flex;
    gap: 3px;
    align-items: center;
    flex-wrap: nowrap;
    overflow: hidden;
}

.compact-reaction-pill {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 2px 6px;
    border-radius: 10px;
    background: rgba(255, 255, 255, 0.08);
    border: 1px solid rgba(255, 255, 255, 0.06);
    font-size: 0.85em;
    line-height: 1;
    transition: background 0.15s ease, transform 0.15s ease;
    cursor: default;
    white-space: nowrap;
}

.compact-reaction-pill:hover {
    background: rgba(255, 255, 255, 0.15);
    transform: scale(1.08);
}

.compact-reaction-count {
    font-size: 0.8em;
    font-weight: 600;
    color: rgba(255, 255, 255, 0.7);
    min-width: 8px;
    text-align: center;
}

.compact-reaction-overflow {
    font-size: 0.72em;
    color: rgba(255, 255, 255, 0.45);
    background: rgba(255, 255, 255, 0.04);
    border-color: rgba(255, 255, 255, 0.04);
    font-style: italic;
}

.compact-card-badges {
    display: flex;
    gap: 4px;
    align-items: center;
    flex-shrink: 0;
}

/* Badge pill (shared by comment and task badges) */
.compact-badge-pill {
    display: inline-flex;
    align-items: center;
    gap: 2px;
    padding: 2px 6px;
    border-radius: 10px;
    font-size: 0.75em;
    line-height: 1;
    white-space: nowrap;
    transition: background 0.15s ease, opacity 0.15s ease;
}

.compact-badge-icon {
    font-size: 0.9em;
    flex-shrink: 0;
}

.compact-badge-count {
    font-weight: 600;
    min-width: 8px;
    text-align: center;
}

.compact-badge-label {
    font-weight: 500;
    max-width: 64px;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Comment badge */
.compact-badge-comment {
    background: rgba(59, 130, 246, 0.12);
    border: 1px solid rgba(59, 130, 246, 0.15);
    color: rgba(147, 197, 253, 0.9);
}

.compact-card:hover .compact-badge-comment {
    background: rgba(59, 130, 246, 0.2);
}

/* Task status badges in meta bar */
.compact-badge-task {
    border: 1px solid transparent;
}

.compact-badge-task.task-status-gtg {
    background: rgba(40, 167, 69, 0.12);
    border-color: rgba(40, 167, 69, 0.18);
    color: rgba(110, 231, 183, 0.9);
}

.compact-badge-task.task-status-check {
    background: rgba(255, 193, 7, 0.12);
    border-color: rgba(255, 193, 7, 0.18);
    color: rgba(255, 220, 100, 0.9);
}

.compact-badge-task.task-status-attention,
.compact-badge-task.task-status-needs-attention {
    background: rgba(220, 53, 69, 0.12);
    border-color: rgba(220, 53, 69, 0.18);
    color: rgba(248, 150, 160, 0.9);
}

.compact-badge-task.task-status-no-action {
    background: rgba(108, 117, 125, 0.1);
    border-color: rgba(108, 117, 125, 0.15);
    color: rgba(200, 200, 200, 0.7);
}

.compact-card:hover .compact-badge-task {
    opacity: 1;
}

/* Time badge */
.compact-badge-time {
    background: rgba(139, 92, 246, 0.12);
    border: 1px solid rgba(139, 92, 246, 0.18);
    color: rgba(196, 167, 252, 0.9);
}
.compact-card:hover .compact-badge-time {
    background: rgba(139, 92, 246, 0.22);
}

/* Lifecycle state styling */
.compact-card-idea {
    border-color: rgba(255, 255, 255, 0.1);
}

.compact-card-goal {
    border-color: rgba(255, 193, 7, 0.4);
    box-shadow: 0 0 0 1px rgba(255, 193, 7, 0.15) inset, 0 2px 8px rgba(255, 193, 7, 0.08);
}

.compact-card-goal .compact-card-body {
    background: linear-gradient(180deg, rgba(255, 193, 7, 0.04) 0%, transparent 100%);
}

.compact-card-locked {
    border-color: rgba(40, 167, 69, 0.4);
    box-shadow: 0 0 0 1px rgba(40, 167, 69, 0.12) inset;
}

.compact-card-locked .compact-card-body {
    background: linear-gradient(180deg, rgba(40, 167, 69, 0.03) 0%, transparent 100%);
}

.compact-card-archived {
    opacity: 0.5;
    border-color: rgba(255, 255, 255, 0.05);
    filter: grayscale(30%);
}

.compact-card-archived:hover {
    opacity: 0.75;
    filter: grayscale(10%);
}

.compact-card-completed {
    opacity: 0.75;
    border-color: rgba(40, 167, 69, 0.25);
}

.compact-card-completed:hover {
    opacity: 0.9;
}

.compact-card-completed .compact-card-photo::before {
    content: '✓';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    font-size: 3em;
    color: rgba(40, 167, 69, 0.6);
    z-index: 1;
    text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

/* Lifecycle badge (floating bottom-right of photo) */
.compact-card-lifecycle-badge {
    position: absolute;
    bottom: 8px;
    right: 8px;
    padding: 2px 8px;
    border-radius: 10px;
    font-size: 0.68em;
    font-weight: 600;
    z-index: 2;
    backdrop-filter: blur(4px);
    -webkit-backdrop-filter: blur(4px);
    display: flex;
    align-items: center;
    gap: 2px;
    letter-spacing: 0.02em;
    text-transform: uppercase;
}

.lifecycle-goal {
