/* =============================================================================
   PHASE 5: Polish, Responsiveness, and Edge Cases
   ============================================================================= */

/* --- Card Entrance Animation --- */
@keyframes board-card-enter {
    from {
        opacity: 0;
        transform: translateY(12px) scale(0.97);
    }
    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

.board-view .compact-card {
    animation: board-card-enter 0.3s ease-out both;
}

/* Staggered entrance — each card delays slightly after the previous */
.board-view .compact-card:nth-child(1) { animation-delay: 0s; }
.board-view .compact-card:nth-child(2) { animation-delay: 0.04s; }
.board-view .compact-card:nth-child(3) { animation-delay: 0.08s; }
.board-view .compact-card:nth-child(4) { animation-delay: 0.12s; }
.board-view .compact-card:nth-child(5) { animation-delay: 0.16s; }
.board-view .compact-card:nth-child(6) { animation-delay: 0.2s; }
.board-view .compact-card:nth-child(7) { animation-delay: 0.24s; }
.board-view .compact-card:nth-child(8) { animation-delay: 0.28s; }
.board-view .compact-card:nth-child(n+9) { animation-delay: 0.32s; }

/* --- Single-Item Nudge --- */
.board-single-item-nudge {
    grid-column: 1 / -1;
    display: flex;
    justify-content: center;
    padding: 20px 16px;
}

.single-item-nudge-content {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 24px;
    border-radius: 12px;
    background: rgba(255, 255, 255, 0.06);
    border: 1px dashed rgba(255, 255, 255, 0.15);
    max-width: 500px;
    animation: board-card-enter 0.4s ease-out 0.2s both;
}

.nudge-icon {
    font-size: 1.3em;
    flex-shrink: 0;
}

.nudge-text {
    margin: 0;
    font-size: 0.85em;
    color: rgba(255, 255, 255, 0.6);
    line-height: 1.4;
}

/* --- Focus Visible for Keyboard Navigation --- */
.compact-card:focus-visible {
    outline: 2px solid rgba(99, 102, 241, 0.8);
    outline-offset: 3px;
    box-shadow: 0 0 0 4px rgba(99, 102, 241, 0.2);
}

/* Remove default outline for mouse users */
.compact-card:focus:not(:focus-visible) {
    outline: none;
}

/* --- Enhanced Touch Targets for Mobile --- */
@media (max-width: 480px) {
    .compact-card-body {
        padding: 10px;
    }

    .compact-card-meta {
        margin-top: 6px;
        padding-top: 6px;
        gap: 6px;
    }

    .compact-card-name {
        font-size: 0.9em;
    }

    .compact-card-status {
        padding: 4px 10px;
        font-size: 0.68em;
    }

    .compact-card-lifecycle-badge {
        padding: 3px 10px;
        font-size: 0.64em;
    }

    .compact-reaction-pill {
        padding: 3px 8px;
        font-size: 0.82em;
    }

    .compact-badge-pill {
        padding: 3px 8px;
        font-size: 0.72em;
    }

    /* Ensure touch targets are at least 44px */
    .presentation-suggestion-btn {
        min-height: 44px;
        min-width: 44px;
        padding: 14px 16px;
    }

    .board-empty-state {
        padding: 50px 20px;
    }

    .board-empty-icon {
        font-size: 2.5em;
    }

    .single-item-nudge-content {
        flex-direction: column;
        text-align: center;
        padding: 16px;
    }
}

/* --- Tablet Responsiveness --- */
@media (min-width: 481px) and (max-width: 768px) {
    .compact-card-photo {
        aspect-ratio: 16 / 9;
    }

    .board-empty-state {
        padding: 60px 24px;
    }
}

/* --- Large Desktop (3+ columns) --- */
@media (min-width: 1200px) {
    .itinerary-items-list.board-view {
        grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
        gap: 20px;
    }
}

/* --- Performance: GPU-accelerated transforms --- */
.compact-card {
    will-change: transform;
    -webkit-transform: translateZ(0);
    transform: translateZ(0);
}

/* Remove will-change after animation settles to free GPU memory */
.compact-card.settled {
    will-change: auto;
}

/* --- Sortable interaction during drag: disable pointer events on non-drag cards --- */
.board-view.is-sorting .compact-card:not(.sortable-drag):not(.sortable-chosen) {
    pointer-events: none;
}

/* --- Smooth photo loading --- */
.compact-card-photo {
    background-color: rgba(255, 255, 255, 0.04);
    transition: background-image 0.2s ease;
}

/* --- High contrast mode support --- */
@media (forced-colors: active) {
    .compact-card {
        border: 2px solid ButtonText;
    }

    .compact-card:focus-visible {
        outline: 3px solid Highlight;
    }

    .compact-card-name {
        color: ButtonText;
    }

    .compact-badge-pill {
        border: 1px solid ButtonText;
    }
}

