            console.log(`[Debug] Existing links on Item: ${existingLinks.length}`);
            // Combine and ensure uniqueness (using Set)
            const updatedLinks = Array.from(new Set([...existingLinks, newGalleryRecordId]));

            const updateItemPayload = {
                fields: {
