// PURPOSE: Generates a dynamic sitemap.xml with all product/event URLs for SEO
// URL: https://whatthefunfinder.netlify.app/sitemap.xml

const fetch = require('node-fetch');
const { AIRTABLE_PAT, BASE_ID } = process.env;

const ITEMS_TABLE = 'tblUA4uuS8IYlhKpD';
const SITE_URL = 'https://whatthefun.wtf';

/**
 * Generates a URL-friendly slug from a name string
 * IMPORTANT: This must match the logic in utils.js generateSlug() to avoid redirect issues
 */
function generateSlug(name, recordId, tags = []) {
    if (!name || typeof name !== 'string') {
        return recordId;
    }

    let slug = name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '');

    // Add up to 3 SEO-friendly tags if available (matching utils.js)
    if (tags.length > 0) {
        const seoTags = tags.slice(0, 3).map(tag =>
            tag.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')
        ).filter(tag => tag.length > 0 && !slug.includes(tag));

        if (seoTags.length > 0) {
            slug = `${slug}-${seoTags.join('-')}`;
        }
    }

    // Limit total length for reasonable URLs (matching utils.js - 60 chars max before recordId)
    slug = slug.substring(0, 60);

    // Append full record ID (not shortened) - matching utils.js
    return `${slug}-${recordId}`;
}

/**
 * Escapes special XML characters
 */
function escapeXml(str) {
    if (!str) return '';
    return str
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&apos;');
}

/**
 * Extracts AI tags from AI_Profile field
 */
function extractTags(record) {
    const aiProfileString = record.fields.AI_Profile || record.fields.Rankings;
    if (aiProfileString) {
        try {
            const aiProfile = JSON.parse(aiProfileString);
            return aiProfile.Tags || aiProfile.SearchTerms || [];
        } catch (e) {
            return [];
        }
    }
    return [];
}

exports.handler = async (event) => {
    if (event.httpMethod !== 'GET') {
        return { statusCode: 405, body: 'Method Not Allowed' };
    }

    try {
        console.log("[sitemap] Generating dynamic sitemap...");
        let allRecords = [];
        let offset = null;

        // Fetch minimal fields needed for sitemap
        const fieldsToFetch = ['Name', 'Status', 'AI_Profile', 'Rankings'];
        const fieldsQuery = fieldsToFetch.map(f => `fields%5B%5D=${encodeURIComponent(f)}`).join('&');

        // Only fetch items with 'Available' or 'Featured' status (matching the frontend filtering logic)
        const filterFormula = encodeURIComponent("OR({Status}='Available', {Status}='Featured')");
        const baseUrl = `https://api.airtable.com/v0/${BASE_ID}/${ITEMS_TABLE}?${fieldsQuery}&filterByFormula=${filterFormula}`;

        do {
            let url = baseUrl;
            if (offset) {
                url += `&offset=${offset}`;
            }
            const response = await fetch(url, {
                headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` }
            });

            if (!response.ok) {
                const errorText = await response.text();
                console.error(`[sitemap] Airtable Error:`, errorText);
                throw new Error(`Failed to fetch items. Status: ${response.status}`);
            }
            const data = await response.json();
            allRecords = allRecords.concat(data.records);
            offset = data.offset;
        } while (offset);

        console.log(`[sitemap] Total records fetched: ${allRecords.length}`);

        const now = new Date().toISOString().split('T')[0]; // YYYY-MM-DD format

        // Static pages
        let urlEntries = `
  <url>
    <loc>${SITE_URL}/</loc>
    <lastmod>${now}</lastmod>
    <changefreq>daily</changefreq>
    <priority>1.0</priority>
  </url>
  <url>
    <loc>${SITE_URL}/start-a-plan.html</loc>
    <lastmod>${now}</lastmod>
    <changefreq>weekly</changefreq>
    <priority>0.9</priority>
  </url>`;

        // Dynamic item pages
        for (const record of allRecords) {
            const name = record.fields.Name;
            if (!name) continue;

            const tags = extractTags(record);
            const slug = generateSlug(name, record.id, tags);
            const itemUrl = `${SITE_URL}/item/${slug}`;

            urlEntries += `
  <url>
    <loc>${escapeXml(itemUrl)}</loc>
    <lastmod>${now}</lastmod>
    <changefreq>weekly</changefreq>
    <priority>0.8</priority>
  </url>`;
        }

        const sitemap = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urlEntries}
</urlset>`;

        return {
            statusCode: 200,
            headers: {
                'Content-Type': 'application/xml; charset=utf-8',
                'Cache-Control': 'public, max-age=86400' // Cache for 24 hours
            },
            body: sitemap
        };

    } catch (error) {
        console.error("[sitemap] Function Error:", error.message);
        return {
            statusCode: 500,
            headers: { 'Content-Type': 'application/xml' },
            body: `<?xml version="1.0" encoding="UTF-8"?><error>${escapeXml(error.message)}</error>`
        };
    }
};

// FILE: netlify/functions/toggle-like.js

const fetch = require('node-fetch');
const jwt = require('jsonwebtoken');

// Ensure JWT_SECRET, AIRTABLE_PAT, and BASE_ID are set in Netlify environment variables
const { JWT_SECRET, AIRTABLE_PAT, BASE_ID } = process.env;
const ITEMS_TABLE = 'tblUA4uuS8IYlhKpD'; // Your Items table ID/Name
const LIKED_BY_FIELD = 'Liked By Users'; // Exact field name from Airtable

exports.handler = async (event) => {
    // Validate environment variables
    if (!JWT_SECRET || !AIRTABLE_PAT || !BASE_ID) {
        console.error('[toggle-like] Missing required environment variables');
        return {
            statusCode: 500,
            body: JSON.stringify({ error: 'Server configuration error' })
        };
    }

    if (event.httpMethod !== 'POST') {
        return { statusCode: 405, body: JSON.stringify({ error: 'Method Not Allowed' }) };
    }

    // --- Authentication ---
    const authHeader = event.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
        return { statusCode: 401, body: JSON.stringify({ error: 'Unauthorized: Missing or invalid token' }) };
    }
    const token = authHeader.split(' ')[1];
    let userId;
    try {
        const decoded = jwt.verify(token, JWT_SECRET);
        userId = decoded.userId;
        if (!userId) throw new Error('Invalid token payload.');
    } catch (error) {
        console.error('JWT Verification Error:', error.message);
        return { statusCode: 401, body: JSON.stringify({ error: 'Unauthorized: Invalid or expired token.' }) };
    }
    // --- End Authentication ---

    try {
        // Defensive: validate request body
        if (!event.body) {
            return { statusCode: 400, body: JSON.stringify({ error: 'Missing request body.' }) };
        }

        let parsedBody;
        try {
            parsedBody = JSON.parse(event.body);
        } catch (parseError) {
            return { statusCode: 400, body: JSON.stringify({ error: 'Invalid JSON in request body.' }) };
        }

        const { itemId } = parsedBody;
        if (!itemId || typeof itemId !== 'string') {
            return { statusCode: 400, body: JSON.stringify({ error: 'Missing or invalid itemId in request body.' }) };
        }

        // Validate itemId format (Airtable record IDs start with 'rec')
        if (!itemId.startsWith('rec')) {
            return { statusCode: 400, body: JSON.stringify({ error: 'Invalid itemId format.' }) };
        }

        console.log(`[toggle-like] User ${userId} toggling like for item ${itemId}`);

        // 1. Fetch the Item record (only the Liked By Users field)
        const getItemUrl = `https://api.airtable.com/v0/${BASE_ID}/${encodeURIComponent(ITEMS_TABLE)}/${itemId}?fields[]=${encodeURIComponent(LIKED_BY_FIELD)}`;
        const itemRes = await fetch(getItemUrl, { headers: { 'Authorization': `Bearer ${AIRTABLE_PAT}` } });

        if (!itemRes.ok) {
            if (itemRes.status === 404) {
                 return { statusCode: 404, body: JSON.stringify({ error: `Item with ID ${itemId} not found.` }) };
            }
            console.error(`Airtable fetch error (${itemRes.status}):`, await itemRes.text());
            throw new Error(`Failed to fetch item ${itemId} from Airtable.`);
        }

        const itemRecord = await itemRes.json();
        const likedUserIds = itemRecord.fields?.[LIKED_BY_FIELD] || []; // Default to empty array if field is missing or null

        // Defensive: ensure likedUserIds is an array
        const safeUserIds = Array.isArray(likedUserIds) ? likedUserIds : [];
        const userIndex = safeUserIds.indexOf(userId);
        let updatedUserIds;
        let liked = false;

        // 2. Determine new state and update list
        if (userIndex > -1) {
            // User already liked it, remove them (unlike)
            updatedUserIds = safeUserIds.filter(id => id !== userId);
            liked = false;
            console.log(`[toggle-like] User ${userId} unliking item ${itemId}.`);
        } else {
            // User hasn't liked it, add them (like)
            updatedUserIds = [...safeUserIds, userId];
            liked = true;
            console.log(`[toggle-like] User ${userId} liking item ${itemId}.`);
        }

        // 3. Update the Item record in Airtable
        const patchUrl = `https://api.airtable.com/v0/${BASE_ID}/${encodeURIComponent(ITEMS_TABLE)}/${itemId}`;
        const payload = {
            fields: {
                [LIKED_BY_FIELD]: updatedUserIds
            }
        };

        const patchRes = await fetch(patchUrl, {
            method: 'PATCH',
            headers: {
                'Authorization': `Bearer ${AIRTABLE_PAT}`,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(payload)
        });

        if (!patchRes.ok) {
            console.error(`Airtable patch error (${patchRes.status}):`, await patchRes.text());
            throw new Error(`Failed to update likes for item ${itemId} in Airtable.`);
        }

        console.log(`[toggle-like] Successfully updated likes for item ${itemId}. New status: ${liked ? 'Liked' : 'Unliked'}`);

        return {
            statusCode: 200,
            body: JSON.stringify({ success: true, liked: liked }) // Return the new liked status
        };

    } catch (error) {
        console.error('[toggle-like] Function Error:', error);
        return {
            statusCode: 500,
            body: JSON.stringify({ error: error.message || 'An internal server error occurred.' })
        };
    }
};

const fetch = require('node-fetch');
// NOTE: We assume CLOUDINARY_API_KEY, CLOUDINARY_API_SECRET, and CLOUDINARY_CLOUD_NAME
// are set as Netlify Environment Variables.
const { CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY, CLOUDINARY_API_SECRET, URL } = process.env;

const CLOUDINARY_AUTH = 'Basic ' + Buffer.from(CLOUDINARY_API_KEY + ':' + CLOUDINARY_API_SECRET).toString('base64');
const AI_PROCESSOR_URL = `${URL || 'http://localhost:8888'}/.netlify/functions/process-image-ai`;

exports.handler = async (event) => {
    if (event.httpMethod !== 'POST') return { statusCode: 405, body: 'Method Not Allowed' };

    try {
        const { tagFilter, maxAssets } = JSON.parse(event.body);

        // 1. Fetch assets from Cloudinary Admin API
        const adminApiUrl = `https://api.cloudinary.com/v1_1/${CLOUDINARY_CLOUD_NAME}/resources/image`;
        const response = await fetch(`${adminApiUrl}?max_results=${maxAssets || 500}&tags=${tagFilter || ''}`, {
            headers: { 'Authorization': CLOUDINARY_AUTH }
        });

        if (!response.ok) {
            const errorData = await response.json();
            throw new Error(`Cloudinary Admin API Error: ${errorData.error.message}`);
        }

        const data = await response.json();
        const assets = data.resources;

        console.log(`Starting bulk AI processing for ${assets.length} assets.`);

        const processPromises = assets.map(asset => 
            // Internal call to the processing function
            fetch(AI_PROCESSOR_URL, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ publicId: asset.public_id })
            })
        );

        // Use Promise.allSettled to ensure one failure doesn't stop the whole batch
        const results = await Promise.allSettled(processPromises);
        const fulfilled = results.filter(r => r.status === 'fulfilled').length;

        return {
            statusCode: 200,
            body: JSON.stringify({ 
                message: `Bulk job completed. Triggered processing for ${assets.length} assets. Successfully processed: ${fulfilled}.`,
                processedCount: assets.length 
            })
        };

    } catch (error) {
        console.error('Bulk Trigger Error:', error.message);
        return { statusCode: 500, body: JSON.stringify({ error: `Bulk trigger failed: ${error.message}` }) };
    }
};

const fetch = require('node-fetch');
const Pusher = require("pusher");

const { AIRTABLE_PAT, BASE_ID, PUSHER_APP_ID, PUSHER_KEY, PUSHER_SECRET, PUSHER_CLUSTER } = process.env;

const pusher = new Pusher({
