/* --- 8. MODAL STYLES (Original) --- */
.modal-overlay {
    display: none;
    opacity: 0;
    transition: opacity 0.3s ease;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background-color: rgba(0, 0, 0, 0.6);
    z-index: 1000;
    justify-content: center;
    align-items: center;
    pointer-events: none;
}
.modal-overlay.active {
    display: flex;
    opacity: 1;
    pointer-events: auto;
}

/* Ensure modals appear above presentation view when both are active */
.presentation-fullpage.active ~ .modal-overlay.active,
body.presentation-active .modal-overlay.active {
    z-index: 1100;
}

/* Specific modal z-index rules for when active */
#detail-modal-overlay.active,
#checkout-modal-overlay.active {
    z-index: 1100;
}

/* Reaction pickers must always appear above modals and presentation */
/* Z-INDEX: TIER 5 - 9100 (above drag operations) */
.reaction-picker,
.comment-reaction-picker {
    z-index: 9100 !important;
}

/* --- Presentation Full Page View --- */
.presentation-fullpage {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    /* Transparent background to show the canvas animation behind */
    background: transparent;
    z-index: 1000;
    justify-content: center;
    align-items: stretch;
}

/* Background canvas for presentation view */
.presentation-bg-canvas {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
    display: block;
    /* Fallback background in case WebGL fails */
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
}

.presentation-fullpage.active {
    display: flex;
}
.presentation-fullpage .presentation-content {
    width: 100%;
    height: 100%;
    max-width: none;
    border-radius: 0;
    box-shadow: none;
    background: transparent;
}

/* Hide all main page elements when presentation view is active */
/* This prevents the catalog from being visible or scrollable behind the presentation */
/* NOTE: #wtf-plans-panel and #wtf-plans-panel-overlay are intentionally NOT hidden here */
/* because they need to overlay on top of the presentation view for quick plan switching */
body.presentation-active #main-header,
body.presentation-active #left-sidebar,
body.presentation-active #right-sidebar,
body.presentation-active #catalog-area,
body.presentation-active #kaleidoscope-bg,
body.presentation-active #marquee-banner-container,
body.presentation-active #loading-message,
body.presentation-active #mobile-summary-bar,
body.presentation-active footer,
body.presentation-active #chat-widget {
    display: none !important;
}

