}

/* Inline Collaborators List - horizontal row of buttons */
.collaborators-inline-list {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

/* Inline collaborators container */
.collaborators-inline {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 8px;
}

/* Collaborator button - shared style for current user and other collaborators */
.collaborator-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 8px 14px;
    min-height: 36px;
    background: rgba(255, 255, 255, 0.9);
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: 20px;
    font-size: 0.9em;
    color: #333;
    cursor: pointer;
    transition: background-color 0.2s, border-color 0.2s, transform 0.1s;
    white-space: nowrap;
    box-sizing: border-box;
}

.collaborator-btn:hover {
    background: rgba(255, 255, 255, 1);
    border-color: rgba(0, 123, 255, 0.3);
    transform: translateY(-1px);
}

/* Current user's account button styling */
.presentation-account-btn.collaborator-btn {
    background: rgba(0, 123, 255, 0.1);
    border-color: rgba(0, 123, 255, 0.3);
    color: #007bff;
    font-weight: 500;
}

.presentation-account-btn.collaborator-btn:hover {
    background: rgba(0, 123, 255, 0.2);
}

/* Other collaborator name buttons */
.collaborator-name-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 8px 14px;
    min-height: 36px;
    background: rgba(255, 255, 255, 0.85);
    border: 1px solid rgba(0, 0, 0, 0.1);
    border-radius: 20px;
    font-size: 0.9em;
    color: #495057;
    cursor: pointer;
    transition: background-color 0.2s, border-color 0.2s;
    white-space: nowrap;
    box-sizing: border-box;
}

.collaborator-name-btn:hover {
    background: rgba(255, 255, 255, 1);
    border-color: rgba(0, 0, 0, 0.2);
}

/* Add/Share button at the end of the collaborators list */
