    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #6c757d;
    margin: 0 0 15px 0;
}

/* Collaborators Carousel Title */
.collaborators-title {
    font-size: 0.85em;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #6c757d;
    margin: 0 0 12px 0;
    text-align: center;
}

/* Collaborators Carousel Wrapper */
.collaborators-carousel-wrapper {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    position: relative;
}

/* Collaborators Carousel (horizontal scrolling list) */
.collaborators-carousel {
    display: flex;
    flex-wrap: nowrap;
    justify-content: flex-start;
    gap: 10px;
    overflow: hidden;
    padding: 4px 0;
    max-width: calc(100% - 80px);
}

/* Carousel navigation buttons */
.collaborators-carousel-btn {
    width: 32px;
    height: 32px;
    border: none;
    border-radius: 50%;
    background: rgba(0, 0, 0, 0.1);
    color: #333;
