    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background-color 0.2s, opacity 0.2s;
    flex-shrink: 0;
}

.collaborators-carousel-btn:hover:not(:disabled) {
    background: rgba(0, 0, 0, 0.2);
}

.collaborators-carousel-btn:disabled {
    opacity: 0.3;
    cursor: not-allowed;
}

.collaborators-list {
    display: flex;
    flex-wrap: wrap;
    justify-content: center;
    gap: 15px;
}

/* Carousel-specific item visibility */
.collaborators-carousel .collaborator-item {
    flex-shrink: 0;
    transition: opacity 0.3s ease, transform 0.3s ease;
}

.collaborators-carousel .collaborator-item.hidden {
