    display: block;
    margin: 12px auto 0;
    padding: 6px 16px;
    border: 1px solid #dee2e6;
    border-radius: 16px;
    background: transparent;
    color: #007bff;
    font-size: 0.85em;
    cursor: pointer;
    transition: background-color 0.2s, border-color 0.2s;
}

.collaborators-expand-btn:hover {
    background: rgba(0, 123, 255, 0.1);
    border-color: #007bff;
}

