/* Individual Item Section Container - each plan item gets its own container */
.itinerary-item-section {
    padding: 0;
    background-color: rgba(255, 255, 255, 0.7);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
