    border: none;
    border-radius: 0;
    box-shadow: none;
    background: transparent;
}

/* Archived item styling - grayscale effect */
.itinerary-item-section.item-status-archived {
    filter: grayscale(100%);
    opacity: 0.7;
}

.itinerary-item-section.item-status-archived:hover {
