    border-color: rgba(129, 199, 132, 0.8);
}

/* Default/neutral state - drag anywhere hint */
.drag-action-tooltip.action-neutral {
    background: rgba(30, 30, 30, 0.9);
    border-color: rgba(100, 100, 100, 0.5);
}

/* ==========================================================================
   RADIAL MENU STYLES
   ========================================================================== */

/* Radial menu mode - transforms drag buckets into a circular radial menu */
.presentation-drag-buckets.radial-mode {
    display: flex !important;
    visibility: visible !important;
    opacity: 1 !important;
    clip: auto !important;
    clip-path: none !important;
    pointer-events: auto !important;
}

/* CRITICAL: Override guard rail for radial menu buckets when presentation is active */
body.presentation-active .radial-menu-container .drag-bucket {
    display: flex !important;
}

/* Radial menu container - positioned at touch/click point */
.radial-menu-container {
    position: fixed;
    width: 0;
    height: 0;
    pointer-events: none;
    z-index: 10000; /* TIER 5: Above all other drag elements and modals */
    /* Center point set via JS */
}

/* Hide standard drag zones in radial mode */
.presentation-drag-buckets.radial-mode .drag-zone-left,
.presentation-drag-buckets.radial-mode .drag-zone-right {
    display: none !important;
}

/* Show radial menu container in radial mode */
.presentation-drag-buckets.radial-mode .radial-menu-container {
    display: block;
    pointer-events: auto;
    visibility: visible !important;
}

/* Radial menu items arranged in a circle */
.radial-menu-container .drag-bucket {
    position: absolute;
    transform-origin: center center;
    pointer-events: auto;
    opacity: 0;
    transform: scale(0.3);
    transition: opacity 0.15s ease-out, transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), visibility 0s linear 0.15s;
    /* Size adjustments for radial layout */
    width: 64px;
    height: 64px;
    min-width: 64px;
    min-height: 64px;
    /* Ensure buckets can become visible - override any inherited hiding */
    visibility: hidden;
    display: flex !important;
    z-index: 10001; /* Above the radial container */
}

/* Radial menu active - show items with animation */
.radial-menu-container.radial-active .drag-bucket {
    opacity: 0.95;
    transform: scale(1);
    visibility: visible !important;
    display: flex !important;
    transition: opacity 0.15s ease-out, transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1), visibility 0s linear 0s;
}

/* Staggered animation for radial menu items - use nth-of-type to skip indicator elements */
.radial-menu-container.radial-active .drag-bucket:nth-of-type(1) { transition-delay: 0ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(2) { transition-delay: 15ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(3) { transition-delay: 30ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(4) { transition-delay: 45ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(5) { transition-delay: 60ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(6) { transition-delay: 75ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(7) { transition-delay: 90ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(8) { transition-delay: 105ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(9) { transition-delay: 120ms; }
.radial-menu-container.radial-active .drag-bucket:nth-of-type(10) { transition-delay: 135ms; }

/* Radial menu bucket hover state */
.radial-menu-container .drag-bucket.drag-over {
    transform: scale(1.25);
    opacity: 1;
    z-index: 10;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5);
}

/* Radial menu bucket labels - proportionally larger for 2x radial layout */
.radial-menu-container .drag-bucket .bucket-icon {
    font-size: 2.4em;
}

.radial-menu-container .drag-bucket .bucket-label {
    font-size: 0.75em;
    letter-spacing: 0.3px;
}

/* Radial center indicator - shows the touch point */
.radial-center-indicator {
    position: absolute;
    width: 32px;
    height: 32px;
    left: -16px;
    top: -16px;
    background: rgba(255, 255, 255, 0.15);
    border: 2px solid rgba(255, 255, 255, 0.4);
    border-radius: 50%;
    pointer-events: none;
    z-index: 10002; /* Above radial buckets */
    animation: radial-pulse 1.5s ease-in-out infinite;
}

@keyframes radial-pulse {
    0%, 100% {
        transform: scale(1);
        opacity: 0.6;
    }
    50% {
        transform: scale(1.2);
        opacity: 0.3;
    }
}

/* Radial direction indicator - shows current drag direction */
.radial-direction-indicator {
    position: absolute;
    width: 4px;
    height: 40px;
    left: -2px;
    top: 0;
    background: linear-gradient(to bottom, rgba(255, 255, 255, 0.8), transparent);
    border-radius: 2px;
    pointer-events: none;
    z-index: 10002; /* Above radial buckets */
    transform-origin: center top;
    opacity: 0;
    transition: opacity 0.1s ease;
}

.radial-menu-container.radial-active .radial-direction-indicator {
    opacity: 0.5;
}

/* Reaction options position adjustment for radial mode */
.radial-menu-container .reaction-options,
.radial-menu-container .quick-comment-options {
    position: absolute;
    left: calc(100% + 8px);
    right: auto;
    top: 50%;
    transform: translateY(-50%);
    flex-direction: row;
    flex-wrap: wrap;
    max-width: 180px;
    gap: 4px;
}

/* Mobile adjustments for radial menu */
@media (max-width: 768px) {
    .radial-menu-container .drag-bucket {
        width: 112px;
        height: 112px;
        min-width: 112px;
        min-height: 112px;
    }

    .radial-menu-container .drag-bucket .bucket-icon {
        font-size: 2em;
    }

    .radial-menu-container .drag-bucket .bucket-label {
        font-size: 0.65em;
    }

    .radial-center-indicator {
        width: 24px;
        height: 24px;
        left: -12px;
        top: -12px;
    }

    .radial-menu-container .reaction-options,
    .radial-menu-container .quick-comment-options {
        max-width: 140px;
    }

    .radial-menu-container .reaction-option {
        width: 32px;
        height: 32px;
        font-size: 1em;
    }

    .radial-menu-container .quick-comment-option {
        padding: 6px 8px;
        font-size: 0.55em;
    }
}

/* ==========================================================================
   END RADIAL MENU STYLES
   ========================================================================== */

/* Sortable ghost styling */
.itinerary-item-section.sortable-ghost {
    opacity: 0.4;
