}

/* Sortable drag styling */
/* Z-INDEX: TIER 4 - 4900 (below drag bucket zones) */
.itinerary-item-section.sortable-drag {
    opacity: 1;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
    z-index: 4900;
    cursor: grabbing;
}

/* Sortable chosen (about to drag) styling */
