}

/* Drag handle indicator on items */
.itinerary-item-section::before {
    content: '';
    position: absolute;
    left: 8px;
    top: 50%;
    transform: translateY(-50%);
    width: 4px;
    height: 40px;
    background: linear-gradient(to bottom,
        transparent 0%,
        rgba(0, 0, 0, 0.15) 20%,
        rgba(0, 0, 0, 0.15) 80%,
        transparent 100%
    );
    border-radius: 2px;
    opacity: 0;
    transition: opacity 0.2s ease;
}

.itinerary-item-section:hover::before {
    opacity: 1;
}

/* Empty state section */
