#presentation-floating-chat-btn.visible {
    opacity: 1;
    pointer-events: auto;
}

#presentation-floating-chat-btn:hover {
    transform: scale(1.08);
    box-shadow: 0 6px 20px rgba(102, 126, 234, 0.5);
}

#presentation-floating-chat-btn:active {
    transform: scale(0.98);
}

#presentation-floating-chat-btn .chat-icon {
    transition: transform 0.3s ease;
}

#presentation-floating-chat-btn.scrolled-to-chat .chat-icon {
    transform: rotate(180deg);
}

#presentation-floating-chat-btn .chat-badge {
