    min-width: 20px;
    height: 20px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    border: 2px solid #fff;
}

/* Message styles within presentation chat */
.itinerary-chat-messages .message-wrapper {
    margin-bottom: 6px;
    display: flex;
    flex-direction: column;
    max-width: 85%;
    position: relative;
}

.itinerary-chat-messages .message-wrapper.sent {
    align-self: flex-end;
}

.itinerary-chat-messages .message-wrapper.received {
    align-self: flex-start;
}

.itinerary-chat-messages .chat-message {
    padding: 8px 12px;
    border-radius: 16px;
    word-wrap: break-word;
    position: relative;
}

.itinerary-chat-messages .message-wrapper.sent .chat-message {
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    color: white;
    box-shadow: 0 2px 8px rgba(102, 126, 234, 0.25);
}

.itinerary-chat-messages .message-wrapper.received .chat-message {
    background-color: rgba(255,255,255,0.9);
    color: #333;
    border: 1px solid rgba(102, 126, 234, 0.15);
    box-shadow: 0 2px 6px rgba(0,0,0,0.06);
}

/* Inline message header in presentation chat */
.itinerary-chat-messages .message-header {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 2px;
}

.itinerary-chat-messages .message-author {
    font-weight: 600;
    font-size: 0.8em;
}

.itinerary-chat-messages .message-wrapper.sent .message-author {
    color: rgba(255,255,255,0.9);
}

.itinerary-chat-messages .message-wrapper.received .message-author {
    color: #667eea;
}

.itinerary-chat-messages .message-header .timestamp {
    font-size: 0.65em;
    color: rgba(255,255,255,0.7);
    margin: 0;
    padding: 0;
}

.itinerary-chat-messages .message-wrapper.received .message-header .timestamp {
    color: #999;
}

.itinerary-chat-messages .message-content {
    font-size: 0.95em;
    line-height: 1.3;
}

/* Message actions for presentation chat */
.itinerary-chat-messages .message-wrapper:hover .message-actions {
    display: flex;
}

.itinerary-chat-messages .message-wrapper .message-actions {
    top: -32px;
}

/* Deleted message styling in presentation chat */
.itinerary-chat-messages .message-wrapper.deleted-message .chat-message {
    background: rgba(108, 117, 125, 0.1);
    color: #6c757d;
    font-style: italic;
    border: 1px dashed rgba(108, 117, 125, 0.3);
}

/* Thread replies in presentation chat */
.itinerary-chat-messages .thread-replies {
    margin-top: 10px;
    padding-left: 18px;
    border-left: 2px solid rgba(102, 126, 234, 0.3);
}

.itinerary-chat-messages .reply-message {
    background: rgba(102, 126, 234, 0.05);
    border-radius: 10px;
}

